+package com.example.contact;
+
+import java.util.Deque;
+import java.util.List;
+import java.util.concurrent.ConcurrentLinkedDeque;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps every message sent so far, in memory, for the lifetime of the application.
+ */
+@Service
+public class ContactMessageStore {
+
+    private final Deque<ContactMessage> messages = new ConcurrentLinkedDeque<>();
+
+    public void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public List<ContactMessage> newestFirst() {
+        return List.copyOf(messages);
+    }
+}
diff --git a/src/main/java/com/example/contact/ContactView.java b/src/main/java/com/example/contact/ContactView.java
new file mode 100644
index 0000000..b024da9
--- /dev/null
+++ b/src/main/java/com/example/contact/ContactView.java
@@ -0,0 +1,147 @@
+package com.example.contact;
+
+import java.util.List;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessageStore store;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog discardDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageStore store) {
+        this.store = store;
+
+        // The server decides what is invalid, so the browser's own checks must not override it
+        nameField.setManualValidation(true);
+        emailField.setManualValidation(true);
+        phoneField.setManualValidation(true);
+        messageField.setManualValidation(true);
+
+        // Every keystroke counts as an edit, so Send is re-enabled straight away
+        List<TextFieldBase<?, String>> inputs = List.of(nameField, emailField, phoneField, messageField);
+        for (TextFieldBase<?, String> input : inputs) {
+            input.setValueChangeMode(ValueChangeMode.EAGER);
+            input.addValueChangeListener(event -> sendButton.setEnabled(true));
+        }
+
+        FormLayout form = new FormLayout(nameField, emailField, phoneField, messageField);
+        form.setColspan(messageField, 2);
+
+        sendButton.addClickListener(event -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.setItems(store.newestFirst());
+
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.add("Leaving this page throws away what you have typed.");
+        discardDialog.getFooter().add(
+                new Button("Keep editing", event -> discardDialog.close()),
+                new Button("Discard", event -> {
+                    discardDialog.close();
+                    pendingNavigation.proceed();
+                }));
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, sendButton, grid, discardDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (nameField.isEmpty() && emailField.isEmpty() && phoneField.isEmpty() && messageField.isEmpty()) {
+            return;
+        }
+        pendingNavigation = event.postpone();
+        discardDialog.open();
+    }
+
+    private void send() {
+        // Enter pressed while the discard dialog is open must not send the message behind it
+        if (discardDialog.isOpened()) {
+            return;
+        }
+
+        ContactMessage draft = new ContactMessage(
+                nameField.getValue().strip(),
+                emailField.getValue().strip(),
+                phoneField.getValue().strip(),
+                messageField.getValue().strip());
+        if (!validate(draft)) {
+            return;
+        }
+
+        store.add(draft);
+        Notification.show("Message sent");
+
+        // Clearing the fields re-enables Send through the listeners, so disable it afterwards
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        sendButton.setEnabled(false);
+
+        grid.setItems(store.newestFirst());
+    }
+
+    private boolean validate(ContactMessage draft) {
+        String nameError = draft.name().isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!draft.email().isEmpty() && !draft.email().matches(EmailValidator.PATTERN)) {
+            emailError = "Enter a valid e-mail address";
+        } else if (draft.email().isEmpty() && draft.phone().isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (draft.message().isEmpty()) {
+            messageError = "Message is required";
+        } else if (draft.message().codePointCount(0, draft.message().length()) > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        nameField.setErrorMessage(nameError);
+        nameField.setInvalid(nameError != null);
+        emailField.setErrorMessage(emailError);
+        emailField.setInvalid(emailError != null);
+        messageField.setErrorMessage(messageError);
+        messageField.setInvalid(messageError != null);
+
+        return nameError == null && emailError == null && messageError == null;
+    }
+}
