+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    // The message store is shared by every test, so each test uses names of its own
+
+    @Test
+    void emptySubmitShowsErrorsAndTheyStayWhenFocusMoves() {
+        send().click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+
+        // Server-side validation owns the invalid state, so moving focus must not clear it
+        nameInput().click();
+        page.locator("h1").click();
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+    }
+
+    @Test
+    void phoneAloneSendsShowsNotificationRowAndClearsTheForm() {
+        fill("Browser Alice", "", "+358 40 123 4567", "Hello from the browser");
+
+        send().click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText("Browser Alice")).isVisible();
+        assertThat(name()).hasJSProperty("value", "");
+        assertThat(message()).hasJSProperty("value", "");
+        assertThat(send()).hasJSProperty("disabled", true);
+    }
+
+    @Test
+    void enterInTheMessageSendsAndEditingReenablesSend() {
+        fill("Browser Bob", "bob@example.com", "", "Sent with Enter");
+
+        messageInput().press("Enter");
+
+        assertThat(page.getByText("Browser Bob")).isVisible();
+        assertThat(send()).hasJSProperty("disabled", true);
+
+        nameInput().click();
+        page.keyboard().press("End");
+        page.keyboard().type("!");
+        assertThat(send()).hasJSProperty("disabled", false);
+    }
+
+    @Test
+    void shiftEnterInTheMessageInsertsANewLineInsteadOfSending() {
+        fill("Browser Carol", "", "555 0100", "first line");
+
+        messageInput().press("End");
+        messageInput().press("Shift+Enter");
+        page.keyboard().type("second line");
+
+        assertThat(message()).hasJSProperty("value", "first line\nsecond line");
+        assertThat(send()).hasJSProperty("disabled", false);
+    }
+
+    @Test
+    void invalidEmailShowsItsMessageInTheBrowser() {
+        fill("Browser Dan", "not-an-email", "555 0101", "Hi");
+
+        send().click();
+
+        assertThat(page.getByText("Enter a valid e-mail address")).isVisible();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStaysPut() {
+        fill("Browser Erin", "", "", "");
+
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        assertThat(page).hasURL(url("contact"));
+
+        page.getByText("Keep editing", new Page.GetByTextOptions().setExact(true)).click();
+
+        assertThat(page.getByText("Keep editing")).isHidden();
+        assertThat(page).hasURL(url("contact"));
+        assertThat(name()).hasJSProperty("value", "Browser Erin");
+    }
+
+    @Test
+    void discardingFromTheDialogGoesToTheAboutView() {
+        fill("Browser Frank", "", "", "");
+
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+        page.getByText("Discard", new Page.GetByTextOptions().setExact(true)).click();
+
+        assertThat(page).hasURL(url("about"));
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterruptedAndDoesNotReload() {
+        page.evaluate("window.__noReload = 'still here'");
+
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+
+        assertThat(page).hasURL(url("about"));
+        assertThat(page.getByText("Discard your message?")).isHidden();
+        assertEquals("still here", page.evaluate("window.__noReload"));
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterAReload() {
+        fill("Browser Grace", "", "555 0102", "Survives a reload");
+        send().click();
+        assertThat(page.getByText("Browser Grace")).isVisible();
+
+        page.reload();
+
+        assertThat(page.getByText("Browser Grace")).isVisible();
+        assertThat(page.getByText("Survives a reload")).isVisible();
+    }
+
+    @Test
+    void enterOnTheFocusedSendButtonSendsExactlyOnce() {
+        fill("Browser Ivan", "", "555 0103", "Once only");
+
+        send().focus();
+        page.keyboard().press("Enter");
+
+        assertThat(page.getByText("Browser Ivan")).hasCount(1);
+        assertThat(page.getByText("Name is required")).isHidden();
+        assertThat(send()).hasJSProperty("disabled", true);
+    }
+
+    @Test
+    void browserForwardWithTypedInputAsksFirst() {
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+        assertThat(page).hasURL(url("about"));
+
+        page.goBack();
+        assertThat(page).hasURL(url("contact"));
+        fill("Browser Judy", "", "", "");
+
+        page.goForward();
+
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        assertThat(page).hasURL(url("contact"));
+    }
+
+    private String url(String view) {
+        return "http://localhost:" + port + "/" + view;
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        nameInput().fill(name);
+        EmailFieldElement.getByLabel(page, "Email").getLocator().locator("input").fill(email);
+        TextFieldElement.getByLabel(page, "Phone").getLocator().locator("input").fill(phone);
+        messageInput().fill(message);
+    }
+
+    private Locator name() {
+        return TextFieldElement.getByLabel(page, "Name").getLocator();
+    }
+
+    private Locator nameInput() {
+        return name().locator("input");
+    }
+
+    private Locator message() {
+        return page.locator("vaadin-text-area");
+    }
+
+    private Locator messageInput() {
+        return message().locator("textarea");
+    }
+
+    private Locator send() {
+        return page.locator("vaadin-button", new Page.LocatorOptions().setHasText("Send"));
+    }
+}
