+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.shared.HasValidationProperties;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+// The message store is a shared singleton, so assertions look at the newest row and at counts taken before each action
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingAboutLinkAndEmptyEnabledForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("About", find(RouterLink.class).single().getText());
+        assertEquals("", nameField().getValue());
+        assertEquals("", emailField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageField().getValue());
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void emptyFormMarksEveryFailingFieldAndSendsNothing() {
+        navigate(ContactView.class);
+        int rowsBefore = rowCount();
+
+        test(sendButton()).click();
+
+        assertInvalid(nameField(), "Name is required");
+        assertInvalid(emailField(), "Give an e-mail address or a phone number");
+        assertInvalid(messageField(), "Message is required");
+        assertValid(phoneField());
+        assertEquals(rowsBefore, rowCount());
+        assertTrue(notifications().isEmpty());
+    }
+
+    @Test
+    void blankNameIsRejected() {
+        navigate(ContactView.class);
+        fill("   ", "", "555 1234", "Hello");
+
+        test(sendButton()).click();
+
+        assertInvalid(nameField(), "Name is required");
+        assertValid(emailField());
+        assertValid(messageField());
+        assertTrue(notifications().isEmpty());
+    }
+
+    @Test
+    void malformedEmailIsRejectedEvenWhenPhoneIsGiven() {
+        navigate(ContactView.class);
+        fill("Alice", "not-an-email", "555 1234", "Hello");
+
+        test(sendButton()).click();
+
+        assertInvalid(emailField(), "Enter a valid e-mail address");
+        assertValid(nameField());
+        assertValid(messageField());
+        assertTrue(notifications().isEmpty());
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndSendingShowsTheMessageAndClearsTheForm() {
+        navigate(ContactView.class);
+        int rowsBefore = rowCount();
+        fill("Alice", "", "+358 40 123 4567", "Hello there");
+
+        test(sendButton()).click();
+
+        assertEquals(rowsBefore + 1, rowCount());
+        assertEquals("Alice", cellText(0, 0));
+        assertEquals("Hello there", cellText(0, 3));
+        assertEquals(1, notifications().size());
+        assertTrue(notificationText().contains("Message sent"));
+        assertEquals("", nameField().getValue());
+        assertEquals("", emailField().getValue());
+        assertEquals("", phoneField().getValue());
+        assertEquals("", messageField().getValue());
+        assertFalse(sendButton().isEnabled());
+    }
+
+    @Test
+    void emailAloneIsEnough() {
+        navigate(ContactView.class);
+        int rowsBefore = rowCount();
+        fill("Bob", "bob@example.com", "", "Hi");
+
+        test(sendButton()).click();
+
+        assertEquals(rowsBefore + 1, rowCount());
+        assertEquals("bob@example.com", cellText(0, 1));
+    }
+
+    @Test
+    void messageOfExactly500CharactersIsAccepted() {
+        navigate(ContactView.class);
+        int rowsBefore = rowCount();
+        fill("Dana", "", "555", "x".repeat(500));
+
+        test(sendButton()).click();
+
+        assertEquals(rowsBefore + 1, rowCount());
+    }
+
+    @Test
+    void messageOver500CharactersIsRejected() {
+        navigate(ContactView.class);
+        fill("Dana", "", "555", "x".repeat(501));
+
+        test(sendButton()).click();
+
+        assertInvalid(messageField(), "Message must be at most 500 characters");
+        assertTrue(notifications().isEmpty());
+    }
+
+    @Test
+    void enterSendsAndSendStaysDisabledUntilTheNextEdit() {
+        navigate(ContactView.class);
+        fill("Erin", "erin@example.com", "", "Via Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Erin", cellText(0, 0));
+        assertFalse(sendButton().isEnabled());
+
+        test(messageField()).setValue("Another one");
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void enterOnAnInvalidFormShowsErrorsAndSendsNothing() {
+        navigate(ContactView.class);
+        int rowsBefore = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertInvalid(nameField(), "Name is required");
+        assertEquals(rowsBefore, rowCount());
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        fill("Carol", "", "123", "Hi");
+        test(sendButton()).click();
+        int rowsBefore = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(rowsBefore, rowCount());
+        assertEquals(1, notifications().size());
+        assertValid(nameField());
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStaysOnTheView() {
+        navigate(ContactView.class);
